BEGIN TRANSACTION;
CREATE TABLE crawl_runs (
	id VARCHAR(36) NOT NULL, 
	started_at DATETIME NOT NULL, 
	finished_at DATETIME, 
	status VARCHAR(32) NOT NULL, 
	pages_requested INTEGER NOT NULL, 
	pages_fetched INTEGER NOT NULL, 
	rows_seen INTEGER NOT NULL, 
	new_notices INTEGER NOT NULL, 
	existing_notices INTEGER NOT NULL, 
	new_matters INTEGER NOT NULL, 
	changed_matters INTEGER NOT NULL, 
	errors INTEGER NOT NULL, 
	total_records_reported INTEGER, 
	error_summary TEXT, 
	PRIMARY KEY (id)
);
CREATE TABLE matters (
	id VARCHAR(36) NOT NULL, 
	canonical_key VARCHAR(320) NOT NULL, 
	debtor_name VARCHAR(300) NOT NULL, 
	normalized_name VARCHAR(300) NOT NULL, 
	cin VARCHAR(32), 
	industry VARCHAR(80) NOT NULL, 
	subindustry VARCHAR(120), 
	classification_method VARCHAR(40) NOT NULL, 
	classification_confidence FLOAT NOT NULL, 
	needs_review BOOLEAN NOT NULL, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id)
);
CREATE TABLE notices (
	id VARCHAR(36) NOT NULL, 
	matter_id VARCHAR(36) NOT NULL, 
	crawl_run_id VARCHAR(36), 
	fingerprint VARCHAR(64) NOT NULL, 
	source_url_hash VARCHAR(64) NOT NULL, 
	revision_number INTEGER NOT NULL, 
	is_current BOOLEAN NOT NULL, 
	resolution_professional VARCHAR(250), 
	eoi_deadline DATE, 
	prospective_applicants_date DATE, 
	objections_deadline DATE, 
	form_g_url TEXT, 
	listing_url TEXT NOT NULL, 
	source_page INTEGER NOT NULL, 
	remarks TEXT, 
	pdf_sha256 VARCHAR(64), 
	pdf_bytes INTEGER, 
	pdf_text_excerpt TEXT, 
	pdf_extract_status VARCHAR(40), 
	raw_row_json TEXT NOT NULL, 
	first_seen_at DATETIME NOT NULL, 
	last_seen_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_notice_fingerprint UNIQUE (fingerprint), 
	FOREIGN KEY(matter_id) REFERENCES matters (id) ON DELETE CASCADE, 
	FOREIGN KEY(crawl_run_id) REFERENCES crawl_runs (id)
);
CREATE INDEX ix_crawl_runs_started_at ON crawl_runs (started_at);
CREATE INDEX ix_crawl_runs_status ON crawl_runs (status);
CREATE INDEX ix_matters_cin ON matters (cin);
CREATE UNIQUE INDEX ix_matters_canonical_key ON matters (canonical_key);
CREATE INDEX ix_matters_debtor_name ON matters (debtor_name);
CREATE INDEX ix_matters_industry ON matters (industry);
CREATE INDEX ix_matters_normalized_name ON matters (normalized_name);
CREATE INDEX ix_matters_needs_review ON matters (needs_review);
CREATE INDEX ix_notices_source_url_hash ON notices (source_url_hash);
CREATE INDEX ix_notices_pdf_sha256 ON notices (pdf_sha256);
CREATE INDEX ix_notices_eoi_deadline ON notices (eoi_deadline);
CREATE INDEX ix_notice_matter_current ON notices (matter_id, is_current);
CREATE INDEX ix_notices_last_seen_at ON notices (last_seen_at);
CREATE INDEX ix_notices_crawl_run_id ON notices (crawl_run_id);
CREATE INDEX ix_notices_matter_id ON notices (matter_id);
CREATE INDEX ix_notices_is_current ON notices (is_current);
COMMIT;
